// NewX2APPDUUnknownExtension builds a checked, owned unknown CHOICE alternative.
func NewX2APPDUUnknownExtension(index uint64, contents []byte, options ...aper.BuildOption) (X2APPDU, error) {
	budget, err := aper.BuildBudget(options...)
	if err != nil {
		return X2APPDU{}, aper.OperationError(err, "X2APPDUUnknownExtension")
	}
	extension, err := aper.BuildChoiceExtension(index, contents, budget)
	if err != nil {
		return X2APPDU{}, aper.OperationError(err, "X2APPDUUnknownExtension")
	}
	value := X2APPDU{UnknownExtension: &extension}
	if _, err := X2apInternalX2APPDUMarshalAPERBudget(&value, budget, false); err != nil {
		return X2APPDU{}, aper.OperationError(err, "X2APPDUUnknownExtension")
	}
	return value, aper.OperationError(nil, "X2APPDUUnknownExtension")
}
